          "type": "array",
          "items": {
            "type": "string"
          }
        }
      },
      "additionalProperties": false
    },
    "_meta": {
      "type": "object",
      "description": "Key that avoids calling the script per host",
      "required": [
        "hostvars"
      ],
      "properties": {
        "hostvars": {
          "type": "object",
