      "description": "A geometry object comprised of multiple polygons. ",
      "example": "../examples/geometryObject.json",
      "translation": {
        "ISO 19115-2": [
          "EX_Extent > geographicElement > EX_BoundingPolygon > polygon > MultiGeometry > geometryMembers > Polygon[ ]"
        ]
